const Gallery421Multiple = ({  galleries, setHideMenu, setCurrentIndex }:any) => {
    const count = useRef(0)
    const calcGalleryOffset = ( gallery : any[] ) => {
        // the problem this is addresses is: the offset should be equal to the total length
        // of all galleries that came before it (i.e. gallery.length is added to test.current 
        // before it should be (see: note-1)). However, since we have to do the 
        // count.current += gallery.length before we return the value (see: note-2), we must 
        // subtract the current gallery.length from count.current.
        return count.current - gallery.length
    }
    
    return (
        <>
            { galleries.map(( gallery : any[], index : any )=>{
                count.current += gallery.length     // note-1
                return <Gallery421                  // note-2
                    key={ index }
                    offset={ calcGalleryOffset(gallery) } 
                    setCurrentIndex={ setCurrentIndex }
                    setHideMenu={ setHideMenu } 
                    gallery={ gallery }
                />
            })}
        </>
    )
}

const Gallery421 = ({ gallery, setHideMenu, setCurrentIndex, offset } : any ) => {
    const gutter : number = 30
    const n : any = {
        desktop : 4,
        tablet : 2, 
        mobile : 1, 
    }
    const desktop : any = {
        breakpoint : 10000, 
        width : `calc(${100/n.desktop}% - ${gutter/n.desktop}px)`,
        gutter : gutter / (n.desktop-1), 
    }
    const tablet : any = {
        breakpoint : 1024, 
        width : `calc(${100/n.tablet}% - ${gutter/n.desktop}px)`,
        gutter : gutter / (n.desktop-1),
    }
    const mobile : any = {
        breakpoint : 766, 
        width : `calc(${100/n.mobile}% - ${gutter/n.desktop}px)`,
        gutter : gutter / (n.desktop-1),
    }

    return (
        <>  

            { gallery && gallery.map(( item : any, index : number )=>{
                return (<>
                    
                    { <div {...css({  
                        height : 50, 
                        width : desktop.gutter, 
                        display : index > 0 ? 'inline-block' : 'none', 
                        // backgroundColor : 'red',
                        [ on( tablet.breakpoint ) ]:{
                            display : index % 2 === 0 ? 'none' : 'inline-block',
                            width : tablet.gutter
                        },
                        [ on( mobile.breakpoint ) ]:{
                            display : 'none',
                            width : mobile.gutter
                        },

                    })}/>}
                 
                    <div onClick={()=>{
                        if(setHideMenu) setHideMenu( true );
                        if(setCurrentIndex) setCurrentIndex( index + (offset ?? 0 ) );
                    }} {...css({ 
                        display : 'inline-block',
                        width : desktop.width, 
                        overflow : 'hidden',
                        aspectRatio : '1 / 0.75', 
                        borderRadius : 10, 
                        backgroundPosition : 'center', 
                        backgroundImage : `url(${ item?.image ??getImagePlaceholder() })`, 
                        backgroundSize : 'cover',
                        marginBottom : 10,
                        [ on( tablet.breakpoint ) ]:{
                            width : tablet.width,
                            marginBottom : 10    
                        },
                        [ on( mobile.breakpoint ) ]:{
                            width : mobile.width, 
                            marginBottom : 14
                        }
                        
                    })}>
                        <div {...css({ 
                            width : '100%', 
                            height : '100%', 
                            cursor : 'pointer',
                            backgroundColor : 'rgba(0,0,0,0.0)',
                            transition: "350ms", 
                            [ onHover ] : {
                                backgroundColor : 'rgba(0,0,0,0.6)',
                            }
                        })}/>
                    
                    </div>   
                </>)

            })}
            
            
            {/* <Hide on={desktop.breakpoint}><SpacerV h={(gutter/n.desktop)+1}/></Hide> */}

            
        </>
    )
}


